                end
            end
            for(int i1=0; i1<4; i1++) begin
                if(rd_mux_addr == 12'h120 + (12)'(i0) * 12'h100 + (12)'(i1) * 12'h4) begin
                    readback_data_var[31:0] = field_storage.queue[i0].payload[i1].value.value;
                end
            end
        end
        readback_data = readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr & ~decoded_req_is_external;
        readback_err = decoded_err;
    end

    assign external_rd_ack = readback_external_rd_ack;
    assign cpuif_rd_ack = readback_done | readback_external_rd_ack;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
